use kino_core::commands::{dispatch,Session};
use serde_json::json;
#[test]fn baking_rejects_spatial_and_effect_mask(){let mut s=Session::new();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].as_str().unwrap().to_string();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();let e=dispatch(&mut s,"add_effect",&json!({"clip_id":c,"kind":"exposure","strings":{"mask_layer":"any"}})).unwrap()["effect_id"].as_str().unwrap().to_string();assert!(dispatch(&mut s,"export_grade_lut",&json!({"clip_id":c,"time":0,"path":"/tmp/no-masked.cube"})).is_err());dispatch(&mut s,"remove_effect",&json!({"clip_id":c,"effect_id":e})).unwrap();dispatch(&mut s,"add_effect",&json!({"clip_id":c,"kind":"halation"})).unwrap();assert!(dispatch(&mut s,"export_grade_lut",&json!({"clip_id":c,"time":0,"path":"/tmp/no-spatial.cube"})).is_err());}
#[test]fn serialized_managed_grade_roundtrip(){let mut s=Session::new();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].as_str().unwrap().to_string();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();dispatch(&mut s,"set_color_curve",&json!({"clip_id":c,"channel":"m","points":[[0,0],[0.2,0.3],[1,1]]})).unwrap();let serialized=serde_json::to_string(&s.project).unwrap();let restored:kino_core::model::Project=serde_json::from_str(&serialized).unwrap();let orig=s.project.find_clip(&c).unwrap();let back=restored.find_clip(&c).unwrap();assert_eq!(orig.effects[0].kind,back.effects[0].kind);assert_eq!(serde_json::to_value(&orig.effects).unwrap(),serde_json::to_value(&back.effects).unwrap());}
